//! Test images for the trace core, committed under `tests/fixtures/trace/core-*.png` and
//! regenerated by `cargo test write_fixtures -- --ignored`.

use image::{Rgba, RgbaImage};
use std::path::PathBuf;

pub const WHITE: [u8; 3] = [255, 255, 255];
pub const RED: [u8; 3] = [220, 30, 30];
pub const BLUE: [u8; 3] = [40, 80, 200];
pub const GREEN: [u8; 3] = [30, 160, 60];
/// The near-white subject in `core-edge`: delta E about 3.5 from white.
pub const PALE: [u8; 3] = [245, 245, 245];
/// Its outline: delta E about 18 from white, so a tolerance of 25 crosses it.
pub const OUTLINE: [u8; 3] = [200, 200, 200];

pub const DISC_CENTRE: (f32, f32) = (64.0, 64.0);
pub const DISC_RADIUS: f32 = 48.0;
pub const ISLAND_RADIUS: f32 = 10.0;
/// `core-square`: a 2 x 2 in square at 100 px per inch.
pub const SQUARE: (u32, u32, u32, u32) = (100, 300, 100, 300);
pub const SMALL_DOT: ((f32, f32), f32) = ((20.0, 20.0), 1.5);
pub const BIG_DOT: ((f32, f32), f32) = ((80.0, 70.0), 20.0);
/// `core-edge`: the subject square, outline 2 px wide inside it.
pub const EDGE_SQUARE: (u32, u32) = (32, 96);

pub fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/trace")
}

pub fn load(name: &str) -> RgbaImage {
    let path = dir().join(format!("core-{name}.png"));
    image::open(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display())).to_rgba8()
}

fn filled(w: u32, h: u32, rgb: [u8; 3]) -> RgbaImage {
    RgbaImage::from_pixel(w, h, Rgba([rgb[0], rgb[1], rgb[2], 255]))
}

fn disc(img: &mut RgbaImage, centre: (f32, f32), radius: f32, rgb: [u8; 3]) {
    for (x, y, p) in img.enumerate_pixels_mut() {
        if in_disc((x, y), centre, radius) {
            *p = Rgba([rgb[0], rgb[1], rgb[2], 255]);
        }
    }
}

pub fn in_disc((x, y): (u32, u32), centre: (f32, f32), radius: f32) -> bool {
    (x as f32 + 0.5 - centre.0).powi(2) + (y as f32 + 0.5 - centre.1).powi(2) <= radius * radius
}

fn rect(img: &mut RgbaImage, (x0, x1, y0, y1): (u32, u32, u32, u32), rgb: [u8; 3]) {
    for y in y0..y1 {
        for x in x0..x1 {
            img.put_pixel(x, y, Rgba([rgb[0], rgb[1], rgb[2], 255]));
        }
    }
}

/// White, a red disc, a white island inside the disc.
pub fn disc_fixture() -> RgbaImage {
    let mut img = filled(128, 128, WHITE);
    disc(&mut img, DISC_CENTRE, DISC_RADIUS, RED);
    disc(&mut img, DISC_CENTRE, ISLAND_RADIUS, WHITE);
    img
}

/// A black 200 px square centred on 400 px of white.
pub fn square_fixture() -> RgbaImage {
    let mut img = filled(400, 400, WHITE);
    rect(&mut img, SQUARE, [0, 0, 0]);
    img
}

/// Blue field, green rectangle, red disc.
pub fn three_fixture(size: u32) -> RgbaImage {
    let s = size as f32 / 192.0;
    let mut img = filled(size, size, BLUE);
    rect(&mut img, ((24.0 * s) as u32, (100.0 * s) as u32, (24.0 * s) as u32, (168.0 * s) as u32), GREEN);
    disc(&mut img, (130.0 * s, 110.0 * s), 40.0 * s, RED);
    img
}

/// White with a 3 px and a 40 px black dot.
pub fn speckle_fixture() -> RgbaImage {
    let mut img = filled(128, 128, WHITE);
    disc(&mut img, SMALL_DOT.0, SMALL_DOT.1, [0, 0, 0]);
    disc(&mut img, BIG_DOT.0, BIG_DOT.1, [0, 0, 0]);
    img
}

/// White with a near-white square whose only boundary is a 2 px pale grey outline.
pub fn edge_fixture() -> RgbaImage {
    let (a, b) = EDGE_SQUARE;
    let mut img = filled(128, 128, WHITE);
    rect(&mut img, (a, b, a, b), OUTLINE);
    rect(&mut img, (a + 2, b - 2, a + 2, b - 2), PALE);
    img
}

pub fn all() -> [(&'static str, RgbaImage); 5] {
    [("disc", disc_fixture()), ("square", square_fixture()), ("three", three_fixture(192)), ("speckle", speckle_fixture()), ("edge", edge_fixture())]
}

#[test]
#[ignore = "writes tests/fixtures/trace/core-*.png; run to regenerate"]
fn write_fixtures() {
    std::fs::create_dir_all(dir()).unwrap();
    for (name, img) in all() {
        img.save(dir().join(format!("core-{name}.png"))).unwrap();
    }
}

#[test]
fn committed_fixtures_match_generator() {
    for (name, img) in all() {
        assert_eq!(load(name), img, "core-{name}.png is stale; run write_fixtures");
    }
}
